from pathlib import Path
from typing import Any

from config.models import SftStageConfig


def expect_sft_config(stage_config: Any) -> SftStageConfig:
    if not isinstance(stage_config, SftStageConfig):
        raise TypeError(f"SFT stage received unexpected config type: {type(stage_config).__name__}")
